const input = $input.first().json;
const ahora = new Date();
const start = new Date(ahora.getTime() + 60 * 60 * 1000).toISOString();
const end_date = new Date(ahora.getTime() + 6 * 24 * 60 * 60 * 1000).toISOString();
const url = "https://api.calendly.com/event_type_available_times?event_type=" + encodeURIComponent(input.calendario_id) + "&start_time=" + start + "&end_time=" + end_date;
return [{
  json: {
    url: url,
    header_name: "Authorization",
    header_value: "Bearer " + input.calendario_key,
    body: "",
    disponibilidad: input.disponibilidad
  }
}];

const response = $input.first().json;
const collection = response.collection || [];
const slotsPorDia = {};
collection.filter(function(s) { return s.status === "available"; }).forEach(function(s) {
  const fecha = new Date(s.start_time).toLocaleDateString("es-CO", { timeZone: "America/Bogota" });
  if (!slotsPorDia[fecha]) slotsPorDia[fecha] = [];
  if (slotsPorDia[fecha].length < 3) {
    slotsPorDia[fecha].push({
      inicio: s.start_time,
      label: new Date(s.start_time).toLocaleString("es-CO", {
        timeZone: "America/Bogota", weekday: "long", day: "numeric", month: "long", hour: "2-digit", minute: "2-digit"
      })
    });
  }
});
var slots = [];
var diasDisponibles = Object.keys(slotsPorDia).slice(0, 3);
diasDisponibles.forEach(function(dia) {
  slots = slots.concat(slotsPorDia[dia].map(function(s) {
    return { inicio: s.inicio, label: s.label + " [" + s.inicio + "]" };
  }));
});
if (slots.length === 0) {
  return [{ json: { tiene_slots: false, mensaje: "No hay horarios disponibles en los proximos 6 dias." } }];
}
return [{ json: { tiene_slots: true, total_slots: slots.length, slots: slots, instruccion: "Presenta estos horarios al lead y pregunta cual le queda mejor. Cuando el lead elija uno, pide su email antes de confirmar." } }];

